    Bug 1959858 - Tweaks to compaction logging. r=darktrojan

    Differential Revision: https://phabricator.services.mozilla.com/D255575

diff --git a/mailnews/base/src/FolderCompactor.cpp b/mailnews/base/src/FolderCompactor.cpp
index 5d1ee907b4e..5b4bcbaf528 100644
--- a/mailnews/base/src/FolderCompactor.cpp
+++ b/mailnews/base/src/FolderCompactor.cpp
@@ -571,7 +571,7 @@ NS_IMETHODIMP FolderCompactor::OnMessageRetained(nsACString const& oldToken,
 // lower-level (mbox) compaction will be reverted no matter what error code
 // we return from this function.
 NS_IMETHODIMP FolderCompactor::OnCompactionComplete(nsresult status) {
-  MOZ_LOG(gCompactLog, LogLevel::Info,
+  MOZ_LOG(gCompactLog, NS_SUCCEEDED(status) ? LogLevel::Info : LogLevel::Error,
           ("OnCompactionComplete(status=0x%" PRIx32 ")", (uint32_t)status));
   nsresult rv = status;
   if (NS_SUCCEEDED(rv)) {
@@ -658,7 +658,7 @@ NS_IMETHODIMP FolderCompactor::OnCompactionComplete(nsresult status) {
 // Any error code returned from here is ignored.
 NS_IMETHODIMP FolderCompactor::OnFinalSummary(nsresult status, int64_t oldSize,
                                               int64_t newSize) {
-  MOZ_LOG(gCompactLog, LogLevel::Info,
+  MOZ_LOG(gCompactLog, NS_SUCCEEDED(status) ? LogLevel::Info : LogLevel::Error,
           ("OnFinalSummary(status=0x%" PRIx32 " oldSize=%" PRId64
            " newSize=%" PRId64 ")",
            (uint32_t)status, oldSize, newSize));
diff --git a/mailnews/local/src/MboxCompactor.cpp b/mailnews/local/src/MboxCompactor.cpp
index d2b9e43e801..5759f59cd62 100644
--- a/mailnews/local/src/MboxCompactor.cpp
+++ b/mailnews/local/src/MboxCompactor.cpp
@@ -237,6 +237,9 @@ NS_IMETHODIMP MboxCompactor::OnDataAvailable(nsIRequest* req,

 // nsIStoreScanListener callback called at end of each message.
 NS_IMETHODIMP MboxCompactor::OnStopRequest(nsIRequest* req, nsresult status) {
+  MOZ_LOG(gCompactLog, NS_SUCCEEDED(status) ? LogLevel::Debug : LogLevel::Error,
+          ("MboxCompactor - OnStopRequest(status=0x%x)", (uint32_t)status));
+
   auto cleanup = mozilla::MakeScopeExit([&] {
     if (mMsgOut) {
       mMsgOut->Close();
@@ -271,6 +274,9 @@ NS_IMETHODIMP MboxCompactor::OnStopScan(nsresult status) {
   nsresult rv = mDestStream->Close();
   mDestStream = nullptr;

+  MOZ_LOG(gCompactLog, NS_SUCCEEDED(status) ? LogLevel::Debug : LogLevel::Error,
+          ("MboxCompactor - OnStopScan(status=0x%x)", (uint32_t)status));
+
   if (NS_SUCCEEDED(rv)) {
     rv = status;
   }
